-- 395: Original BrillaPrep NSMQ subj_nsmq_chemistry speed_race beta questions (batch 001).
-- Curriculum-aligned practice content; not official NSMQ (Primetime) material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_395_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_395_guard;
INSERT INTO _migration_395_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_sr_b001_001' AND NOT (q.topic_id IS 'topic_nsmq_chem_atomic' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How many protons are in the nucleus of a carbon atom?' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS '6' AND q.explanation IS 'The atomic number Z counts the protons in the nucleus. Carbon has 6 protons, so Z = 6; this fixes its position in group 14 of the periodic table.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_sr_b001_001' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_395_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_sr_b001_002' AND NOT (q.topic_id IS 'topic_nsmq_chem_bonding' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What type of bond holds the atoms together within a water molecule?' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS 'Covalent bond' AND q.explanation IS 'Within H₂O, hydrogen and oxygen share electron pairs, forming covalent bonds. (The attraction between separate water molecules is hydrogen bonding, a much weaker intermolecular force.)' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_sr_b001_002' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_395_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_sr_b001_003' AND NOT (q.topic_id IS 'topic_nsmq_chem_organic' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the general molecular formula of alkenes?' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS 'CₙH₂ₙ' AND q.explanation IS 'Alkenes contain one carbon–carbon double bond and follow the general formula CₙH₂ₙ; for n = 2 the compound is ethene, C₂H₄. Alkanes are CₙH₂ₙ₊₂ and alkynes CₙH₂ₙ₋₂.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_sr_b001_003' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_395_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_nsmq_chem_sr_b001_004' AND NOT (q.topic_id IS 'topic_nsmq_chem_equilibrium' AND q.subject_id IS 'subj_nsmq_chemistry' AND q.exam_type_id IS 'exam_nsmq' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the pH of a 0.001 M solution of hydrochloric acid?' AND q.question_type IS 'direct_answer' AND q.round_type IS 'speed_race' AND q.options IS NULL AND q.correct_answer IS '3' AND q.explanation IS 'HCl is a strong acid and ionises fully, so [H⁺] = 0.001 = 10⁻³ M. Then pH = −log₁₀[H⁺] = −log₁₀(10⁻³) = 3.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '1' AND q.time_limit IS '15' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS NULL AND q.command_word IS 'State' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS NULL)) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_nsmq_chem_sr_b001_004' AND NOT (r.batch_id IS 'nsmq-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep practice content aligned to the published NaCCA Ghana secondary curriculum; not official NSMQ or Primetime material.' AND r.source_url IS 'https://nacca.gov.gh/secondary-education-curriculum/' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
